package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length is 7, end is 7. trailer is ' ' (index 6), end becomes 6.
        // second trailer check: buffer[5] is '3', not space/null.
        // Wait, let's look at the logic: 
        // trailer = buffer[end-1] (index 6 is ' '). end becomes 6.
        // trailer = buffer[end-1] (index 5 is '3'). end stays 6.
        // start is 0. Loop 0 to 6.
        // But "000123 " has 7 chars.
        // Let's use a cleaner setup for the logic.
        byte[] buf = "000123\0".getBytes(); // '0','0','0','1','2','3','\0' (len 7)
        long result = TarUtils.parseOctal(buf, 0, 7);
        assertEquals(83L, result); // 123 octal = 83 decimal
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buf = "  0123\0".getBytes(); // ' ', ' ', '0', '1', '2', '3', '\0' (len 7)
        long result = TarUtils.parseOctal(buf, 0, 7);
        assertEquals(10L, result); // 12 octal = 10 decimal
    }

    @Test
    public void testParseOctal_ValidWithMultipleTrailingSpaces() {
        byte[] buf = "0123  \0".getBytes(); // '0','1','2','3',' ',' ','\0' (len 7)
        // end = 7. trailer = buffer[6] (\0). end becomes 6.
        // trailer = buffer[5] (' '). end becomes 5.
        // start = 0. Loop 0 to 5 (0,1,2,3,4). 
        // Wait, if end is 5, it reads indices 0,1,2,3,4. 
        // '0','1','2','3',' ' -> that's not right.
        // Let's trace carefully: '0','1','2','3',' ',' ','\0'
        // idx: 0,1,2,3,4,5,6
        // end=7. trailer=buf[6] (\0). end=6.
        // trailer=buf[5] (' '). end=5.
        // start=0. Loop 0 to <5. Indices: 0,1,2,3,4.
        // buf[4] is ' '. This will trigger IllegalArgumentException in the loop.
        // Let's adjust the test case to match the logic requirement.
        byte[] buf2 = "0123\0 ".getBytes(); // '0','1','2','3','\0',' ' (len 6)
        // end=6. trailer=buf[5] (' '). end=5.
        // trailer=buf[4] (\0). end=4.
        // start=0. Loop 0 to <4 (0,1,2,3). Correct.
        assertEquals(10L, TarUtils.parseOctal(buf2, 0, 6));
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buf = new byte[5];
        buf[0] = 0;
        assertEquals(0L, TarUtils.parseOctal(buf, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buf = "12".getBytes();
        TarUtils.parseOctal(buf, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buf = "0123X".getBytes(); // 'X' is not 0 or ' '
        TarUtils.parseOctal(buf, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buf = "0128\0".getBytes(); // '8' is not octal
        TarUtils.parseOctal(buf, 0, 5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buf = "01A3\0".getBytes();
        TarUtils.parseOctal(buf, 0, 5);
    }

    @Test
    public void testParseOctal_OffsetTesting() {
        byte[] buf = "XYZ0123\0".getBytes();
        // offset 3, length 5 -> "0123\0"
        long result = TarUtils.parseOctal(buf, 3, 5);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_MaxLong() {
        // Octal for a large number
        // 777777777777777777 (18 sevens)
        byte[] buf = "777777777777777777\0".getBytes();
        long result = TarUtils.parseOctal(buf, 0, buf.length);
        assertEquals(0L, 0L); // Placeholder for structure
        // Actually, let's just test a specific large one
        byte[] buf2 = "177777777777777777\0".getBytes();
        long res2 = TarUtils.parseOctal(buf2, 0, buf2.length);
        // This just ensures no overflow crash and correct accumulation
        assertEquals(Long.parseLong("177777777777777777", 8), res2);
    }
}
